-- TABLES

CREATE TABLE attendance_records (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  userId INTEGER NOT NULL,
  userName TEXT,
  date TEXT,
  loginTime TEXT,
  logoutTime TEXT,
  totalHours TEXT,
  ipAddress TEXT,
  location TEXT,
  device TEXT,
  os TEXT,
  browser TEXT,
  status TEXT,
  breaks TEXT -- JSON array
);

CREATE TABLE attendance_sheet (
  userId INTEGER NOT NULL,
  date TEXT NOT NULL,
  status TEXT, logs TEXT DEFAULT '[]',
  PRIMARY KEY (userId, date)
);

CREATE TABLE bookings (
