  origin TEXT,
  destination TEXT,
  departureDate TEXT,
  returnDate TEXT,
  cabin TEXT,
  adults INTEGER,
  children INTEGER,
  infants INTEGER,
  queryStatus TEXT,
  querySource TEXT,
  remarks TEXT,
  partialPayment TEXT,
  pnr TEXT,
  created TEXT,
  modified TEXT
, images TEXT, pnr_details TEXT, trip_type TEXT, currency TEXT, qc_status TEXT DEFAULT NULL, company TEXT DEFAULT 'Get Set Flight', qcNote TEXT);

CREATE TABLE break_logs (
