  isRead INTEGER DEFAULT 0,
  createdBy TEXT,
  created TEXT
, company TEXT DEFAULT 'Get Set Flight');

CREATE TABLE `es_system__auth_user` (
	`id` text PRIMARY KEY NOT NULL,
